def catalogs():
    from src.ui_strings_extra import EXTRA_ROWS
    width = 1 + len(_LANGS)
    tables = {code: {} for code in _LANGS}
    for row in list(_ROWS) + list(EXTRA_ROWS):
        if len(row) != width:
            raise ValueError(f"{row[0]} has {len(row) - 1} languages, expected {len(_LANGS)}")
        key = row[0]
        for code, value in zip(_LANGS, row[1:]):
            tables[code][key] = value
    return tables


CATALOGS = catalogs()
UI_LANGS = _LANGS


def tr(key: str, **fmt):
    from src.i18n import tr as _tr
    return _tr(key, **fmt)
